-- Fresh marked disposable DB only. SQL Auth fixtures; no real user/provider calls.
begin;
create function pg_temp.lr_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Learner intent assertion: %',label;end if;end $$;
create function pg_temp.lr_denied(command text,expected text default '42501') returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=expected then return;end if;raise exception 'Unexpected learner SQLSTATE %',sqlstate;end;raise exception 'Expected learner refusal';end $$;
create function pg_temp.lr_claim(n integer,assurance text default 'aal2',offset_seconds integer default 0) returns void language plpgsql security definer set search_path='' as $$
declare s uuid:=('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;t bigint;
begin select floor(extract(epoch from c.updated_at))::bigint into t from auth.mfa_amr_claims c where c.session_id=s;
perform set_config('request.jwt.claims',jsonb_build_object('sub',('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'session_id',s,'role','authenticated','aal',assurance,'user_metadata',jsonb_build_object('role','owner'),'amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',t+offset_seconds)))::text,true);end $$;
create function pg_temp.lr_fault() returns trigger language plpgsql as $$begin raise exception 'Controlled learner event append failure';end $$;
do $$begin execute format('grant usage on schema %I to authenticated',pg_my_temp_schema()::regnamespace::text);end $$;
insert into auth.users(id,raw_user_meta_data) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,jsonb_build_object('display_name','Learner fixture '||n,'role','owner') from generate_series(1,10)n;
insert into auth.mfa_factors(id,user_id,factor_type,status) select ('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'totp','verified' from generate_series(1,10)n;
insert into auth.sessions(id,user_id,factor_id,aal) select ('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'aal2' from generate_series(1,10)n;
insert into auth.mfa_amr_claims(id,session_id,authentication_method,updated_at) select ('d4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'totp',date_trunc('second',clock_timestamp())-interval '120 seconds' from generate_series(1,10)n;
insert into pipstart_staff_private.members(user_id,active) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,n<>7 from unnest(array[1,2,3,4,7])n;
insert into pipstart_staff_private.roles values('d1000000-0000-4000-8000-000000000001','owner'),('d1000000-0000-4000-8000-000000000002','administrator'),('d1000000-0000-4000-8000-000000000003','administrator'),('d1000000-0000-4000-8000-000000000004','author');
insert into pipstart_staff_private.delegations values('d1000000-0000-4000-8000-000000000003','people.manage_learners');
update public.pipstart_profiles set role='admin' where user_id='d1000000-0000-4000-8000-000000000008';

do $$begin execute format('grant usage on schema %I to service_role',pg_my_temp_schema()::regnamespace::text);end $$;
create temp table provider_test_permits(request_id uuid,dispatch_id uuid,token text,mode text);grant select,insert on provider_test_permits to authenticated,service_role;
select pg_temp.lr_ok(not has_table_privilege('service_role','pipstart_staff_private.learner_provider_permits','SELECT'),'service key has no raw permit access');
select pg_temp.lr_ok(not has_function_privilege('service_role','public.pipstart_staff_learner_claim(uuid,text,text)','EXECUTE'),'service cannot authorize a user claim');
select pg_temp.lr_ok(not has_function_privilege('authenticated','public.pipstart_staff_learner_provider_take(uuid,uuid,text)','EXECUTE'),'user cannot execute a provider permit');
select pg_temp.lr_ok(not has_function_privilege('authenticated','public.pipstart_staff_learner_provider_result(uuid,uuid,text,text)','EXECUTE'),'user cannot forge provider success');
update pipstart_staff_private.control set enabled=true;
set local role authenticated;select pg_temp.lr_claim(3);
select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64));
select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000005','auth_resume',null,'access_change',repeat('a',64));
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_claim('d9000000-0000-4000-8000-000000000001','dispatch',repeat('b',64))$q$);
insert into provider_test_permits select (j->>'request_id')::uuid,(j->>'dispatch_id')::uuid,j->>'permit','dispatch' from (select public.pipstart_staff_learner_claim('d9000000-0000-4000-8000-000000000001','dispatch',repeat('a',64)) j)q;
select pg_temp.lr_ok(not (public.pipstart_staff_learner_claim('d9000000-0000-4000-8000-000000000001','dispatch',repeat('a',64))?'permit'),'replayed claim returns no permit');
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),repeat('b',64))$q$);
reset role;
select pg_temp.lr_denied($q$insert into pipstart_staff_private.members(user_id) values('d1000000-0000-4000-8000-000000000005')$q$);
select pg_temp.lr_denied($q$update public.pipstart_profiles set role='admin' where user_id='d1000000-0000-4000-8000-000000000005'$q$);
set local role service_role;
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_claim('d9000000-0000-4000-8000-000000000001','dispatch',repeat('a',64))$q$);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),repeat('b',64))$q$);
reset role;
delete from pipstart_staff_private.delegations where user_id='d1000000-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),(select token from provider_test_permits))$q$);
reset role;
insert into pipstart_staff_private.delegations values('d1000000-0000-4000-8000-000000000003','people.manage_learners');
update auth.mfa_factors set status='unverified' where user_id='d1000000-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),(select token from provider_test_permits))$q$);
reset role;
update auth.mfa_factors set status='verified' where user_id='d1000000-0000-4000-8000-000000000003';
create trigger controlled_provider_append_fault before insert on pipstart_staff_private.learner_provider_events for each row execute function pg_temp.lr_fault();
set local role service_role;
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),(select token from provider_test_permits))$q$,'P0001');
reset role;
select pg_temp.lr_ok((select state='prepared' from pipstart_staff_private.learner_deliveries) and (select consumed_at is null from pipstart_staff_private.learner_provider_permits),'append failure rolls permit and state back');
drop trigger controlled_provider_append_fault on pipstart_staff_private.learner_provider_events;
set local role service_role;
select public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),(select token from provider_test_permits));
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),(select token from provider_test_permits))$q$);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_result('d9000000-0000-4000-8000-000000000001',gen_random_uuid(),(select token from provider_test_permits),'succeeded')$q$);
reset role;update pipstart_staff_private.control set enabled=false;
select pipstart_staff_private.learner_delivery_review('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),'unknown');
set local role service_role;
select public.pipstart_staff_learner_provider_result('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),(select token from provider_test_permits),'unknown');
select public.pipstart_staff_learner_provider_result('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),(select token from provider_test_permits),'unknown');
reset role;
select pg_temp.lr_ok((select count(*)=3 from pipstart_staff_private.learner_provider_events),'result replay does not append twice');
update pipstart_staff_private.control set enabled=false;
select pg_temp.lr_denied($q$update pipstart_staff_private.control set enabled=true$q$);
select pipstart_staff_private.learner_delivery_review('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits),'observed_desired');
update pipstart_staff_private.control set enabled=true;
-- Fresh inspection is independent of the old action proof and cannot record success.
update auth.mfa_amr_claims set updated_at=date_trunc('second',clock_timestamp())-interval '30 seconds' where session_id='d2000000-0000-4000-8000-000000000003';
set local role authenticated;select pg_temp.lr_claim(3);
select public.pipstart_staff_learner_inspection_receipt('d9000000-0000-4000-8000-000000000001',repeat('c',64));
insert into provider_test_permits select (j->>'request_id')::uuid,(j->>'dispatch_id')::uuid,j->>'permit','inspect' from (select public.pipstart_staff_learner_claim('d9000000-0000-4000-8000-000000000001','inspect',repeat('c',64))j)q;
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_claim('d9000000-0000-4000-8000-000000000001','inspect',repeat('c',64))$q$);
set local role service_role;
select pg_temp.lr_ok((public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits where mode='inspect'),(select token from provider_test_permits where mode='inspect'))->>'status')='inspection_authorized','inspection is a read permit');
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_result('d9000000-0000-4000-8000-000000000001',(select dispatch_id from provider_test_permits where mode='inspect'),(select token from provider_test_permits where mode='inspect'),'succeeded')$q$);
reset role;
select pg_temp.lr_ok((select state='observed_desired' from pipstart_staff_private.learner_deliveries),'inspection does not resolve or rewrite outcome');
select pg_temp.lr_denied($q$delete from pipstart_staff_private.learner_provider_events$q$);
-- Paused trusted cancellation can only revoke a still-unconsumed execution path.
update auth.mfa_amr_claims set updated_at=date_trunc('second',clock_timestamp())-interval '10 seconds' where session_id='d2000000-0000-4000-8000-000000000003';
set local role authenticated;select pg_temp.lr_claim(3);
select public.pipstart_staff_learner_receipt('d9000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000009','auth_resume',null,'access_change',repeat('d',64));
select public.pipstart_staff_learner_prepare('d9000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000009','auth_resume',null,'access_change',repeat('d',64));
insert into provider_test_permits select (j->>'request_id')::uuid,(j->>'dispatch_id')::uuid,j->>'permit','cancel_test' from (select public.pipstart_staff_learner_claim('d9000000-0000-4000-8000-000000000002','dispatch',repeat('d',64))j)q;
select pg_temp.lr_claim(1);
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_claim('d9000000-0000-4000-8000-000000000002','dispatch',repeat('d',64))$q$);
reset role;update pipstart_staff_private.control set enabled=false;
select pipstart_staff_private.learner_delivery_review('d9000000-0000-4000-8000-000000000002',(select dispatch_id from provider_test_permits where mode='cancel_test'),'cancelled');
update pipstart_staff_private.control set enabled=true;
set local role service_role;
select pg_temp.lr_denied($q$select public.pipstart_staff_learner_provider_take('d9000000-0000-4000-8000-000000000002',(select dispatch_id from provider_test_permits where mode='cancel_test'),(select token from provider_test_permits where mode='cancel_test'))$q$);
reset role;
rollback;
